package com.autoops.command.validation;import org.springframework.stereotype.Service;import java.util.*;import java.util.regex.Pattern;@Service public class CommandParameterValidator{private static final Pattern SAFE=Pattern.compile("[a-zA-Z0-9_./:@%+=,-]+");public void validate(Map<String,String> p){for(var e:p.entrySet()){if(e.getValue()==null||!SAFE.matcher(e.getValue()).matches())throw new IllegalArgumentException("Unsafe parameter: "+e.getKey());}}}
